@startuml

class Employee {
  + Name : string
  + SocialSecurityNumber : string
  + Username : string
  + Password : string
}

class Driver extends Employee {
}

class Planner extends Employee {
}

class AdministrativeStaff extends Employee {
  + FieldOfActivity : string
}

class Customer {
  + Name : string
  + BillingAddress : string
}

class PartnerCompany {
  + Name : string
  + Address : string
}

class Vehicle {
  + LicensePlateNumber : string
  + Mileage : int
  + Type : VehicleType
}

enum VehicleType {
  RefrigeratedTruck
  SmallVan
  LoadingPlatform
  BoxTruck
}

class Repair {
  + Duration : string
  + Cost : float
}

class RepairShop {
  + Name : string
  + Address : string
}

class Order {
  + PackageSize : string
  + Comment : string
  + StartTime : datetime
  + FinishTime : datetime
  + PickUpAddress : string
  + DeliveryAddress : string
}

class Assignment {
  + Planner : Planner
}

"1" -- "*" Order : places
"1" -- "*" Order : placed by
"1" -- "*" Order : assigned to
"1" -- "*" Order : completed by
"1" -- "*" Order : uses
"1" -- "0..1" Order : assigned to
"1" -- "*" Repair : undergoes
"1" -- "1" Repair : conducted by
"1" -- "1" Repair : at
"1" -- "*" Order : placed by

@enduml

